mapper.select:
SELECT id, doctor_id, schedule_date, session_type, session_name, start_time, end_time,
       average_consultation_minutes, total_capacity, remaining_capacity,
       next_queue_number, status, version, created_at, updated_at
FROM doctor_schedule_slot
WHERE doctor_id = #{doctorId}
  AND (

        (schedule_date = #{slot.scheduleDate}
         AND start_time < #{slot.endTime}
         AND end_time > #{slot.startTime})

  )

mapper.update:
UPDATE doctor_schedule_slot
SET status = #{status}, version = version + 1
WHERE id = #{id} AND version = #{version}
